contract InvMutTest {
    C c;
    constructor(C _c) payable { c = _c; }

    function run(bytes32 guess1, bytes32 guess2) public payable {
        require(address(this).balance >= 1 ether);
        // lock in a first guess (always succeeds on fresh c)
        c.lockInGuess{value: 1 ether}(guess1);
        // settle (block.number advanced beyond guessed block is enforced by chain state; use try/catch)
        bool settleReverted;
        // settle may revert if block.number <= guesses[msg.sender].block; wrap in try
        // We must use try at top level for the deciding call only, but state-changing calls must be top-level statements;
        // so instead we perform settle at top level and rely on it succeeding: block.number > lock block after lockInGuess.
        c.settle();
        settleReverted = false;
        // after settle, the guess slot is cleared: lockInGuess with any new hash succeeds
        require(address(this).balance >= 1 ether);
        bool rel reverted = false; // placeholder removed below
        rel = false;
        c.lockInGuess{value: 1 ether}(guess2);
        bool secondSettleReverted;
        try c.settle() { secondSettleReverted = false; } catch { secondSettleReverted = true; }
        assert(!settleReverted && !relockReverted && secondSettleReverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) payable { c = _c; }

    function run(bytes32 guess) public payable {
        require(address(this).balance >= 1 ether);
        c.lockInGuess{value: 1 ether}(guess);
        // settle in the same block must revert: block.number == guessed block
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }
        // since settle reverted, the slot is still occupied: another lock reverts
        bool relockReverted;
        require(address(this).balance >= 1 ether);
        try c.lockInGuess{value: 1 ether}(guess) { relockReverted = false; } catch { relockReverted = true; }
        assert(settleReverted && relockReverted);
    }
    receive() external payable {}
}

